2	
3	import com.tainted.community.domain.Comment;
4	import com.tainted.community.domain.CommentRepository;
5	import com.tainted.community.domain.Post;
6	import com.tainted.community.domain.PostRepository;
7	import com.tainted.community.error.PostNotFoundException;
8	import com.tainted.community.event.CommunityEventPublisher;
9	import com.tainted.community.id.IdGenerator;
10	import com.tainted.community.web.dto.CommentResponse;
11	import com.tainted.community.web.dto.CreateCommentRequest;
12	import com.tainted.community.web.dto.CreatePostRequest;
13	import com.tainted.community.web.dto.CreatePostResponse;
14	import com.tainted.community.web.dto.LikeResponse;
15	import com.tainted.community.web.dto.PostResponse;
16	import org.springframework.stereotype.Service;
17	import org.springframework.transaction.annotation.Transactional;
18	
19	import java.time.Clock;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.stream.Collectors;
23	
24	@Service
25	public class CommunityService {
26	
27	    private final PostRepository postRepository;
28	    private final CommentRepository commentRepository;
29	    private final CommunityEventPublisher eventPublisher;
30	    private final IdGenerator idGenerator;
31	    private final Clock clock;
32	
33	    public CommunityService(PostRepository postRepository,
34	                            CommentRepository commentRepository,
35	                            CommunityEventPublisher eventPublisher,
36	                            IdGenerator idGenerator,
37	                            Clock clock) {
38	        this.postRepository = postRepository;
39	        this.commentRepository = commentRepository;
40	        this.eventPublisher = eventPublisher;
41	        this.idGenerator = idGenerator;
42	        this.clock = clock;
43	    }
44	
45	    @Transactional
46	    public CreatePostResponse createPost(CreatePostRequest request) {
47	        Post post = new Post(
48	                idGenerator.newId(),
49	                request.getUserId(),
50	                request.getTitle(),
51	                request.getCategory(),
52	                request.getContent(),
53	                request.getMoodEmoji(),
54	                request.getNickname(),
55	                0,
56	                Instant.now(clock));
57	        postRepository.saveAndFlush(post);
58	        eventPublisher.publishPostCreated(post);
59	        eventPublisher.publishMoodLogged(post);
60	        return new CreatePostResponse(post.getId());
61	    }
62	
63	    @Transactional(readOnly = true)
64	    public List<PostResponse> listPosts() {
65	        return postRepository.findAllByOrderByCreatedAtDesc().stream()
