_IDENT = _re.compile(r"^[A-Za-z_]\w*$")


class SpecError(ValueError):
    """spec 검증 실패 — 필드 경로를 메시지에 담는다 (T8)."""


def _ident(name, ctx):
    if not _IDENT.match(str(name)):
        raise SpecError(f"{ctx}: 잘못된 식별자 '{name}' (영문자/숫자/_만 허용)")
    return name


def esc_java(s):
    return str(s).replace("\\", "\\\\").replace('"', '\\"')


def esc_sql(s):
    return str(s).replace("'", "''")


def _pkg_dir(package):
    return "src/test/java/" + package.replace(".", "/")


def _derive_package(spec, cfg):
    """T1: 우선순위 config.testPackage > spec.testPackage > controllerFile 유추 > 기본."""
    pkg = cfg.get("testPackage") or spec.get("testPackage")
    if pkg:
        return pkg
    cf = spec.get("endpoint", {}).get("controllerFile", "")
    m = _re.search(r"src/(?:main|test)/java/(.+)/[^/]+\.java$", cf)
    if m:
        base = m.group(1).replace("/", ".")
        # 컨트롤러 패키지의 상위(…​.web.x.controller → …)를 blackbox 하위로
        base = _re.sub(r"\.(web|api|controller|rest)(\..*)?$", "", base)
        return base + ".blackbox"
    return DEFAULT_PACKAGE


# ── SQL 합성 ───────────────────────────────────────────────────────────────
def sql_value(v):
    """구조화 값 → SQL 토큰. {ref}: 숫자 시드 ${X} / {refStr}: '${X}' / {expr}: 원문 /
    str: 문자열 리터럴 / int·float: 숫자 / None: NULL."""
    if v is None:
        return "NULL"
    if isinstance(v, dict):
        if "ref" in v:
            return "${%s}" % v["ref"]
        if "refStr" in v:
            return "'${%s}'" % v["refStr"]
        if "expr" in v:
            return str(v["expr"])
        raise ValueError(f"unknown sql value: {v}")
    if isinstance(v, (int, float)):
        return str(v)
    return "'%s'" % esc_sql(v)


def synth_delete(t):
    where = t.get("where") or {}
    if not where:   # T4: 빈 where → 전체 삭제 (WHERE ; 구문오류 방지)
        return f"DELETE FROM {t['table']};"
    conds = " AND ".join(f"{c} = {sql_value(v)}" for c, v in where.items())
    return f"DELETE FROM {t['table']} WHERE {conds};"


NO_FIXTURE = "-- no fixtures required for this endpoint\n"   # SF1: 게이트 위양성 방지


def synth_sql(fixtures, usage):
    if "rawSetupSql" in fixtures or "rawTeardownSql" in fixtures:
        usage["raw_sql"] += 1
        return (fixtures.get("rawSetupSql", "").rstrip() + "\n" or NO_FIXTURE,
                fixtures.get("rawTeardownSql", "").rstrip() + "\n" or NO_FIXTURE)
    if not fixtures.get("setup") and not fixtures.get("teardown"):
        usage["no_fixture"] += 1   # SF1: 픽스처 불필요 EP는 주석 마커 (빈 파일 아님)
        return NO_FIXTURE, NO_FIXTURE
    usage["structured_sql"] += 1
    teardown_stmts = [synth_delete(t) for t in fixtures.get("teardown", [])]
    setup_lines = []
    if fixtures.get("preDelete") and teardown_stmts:
        setup_lines += teardown_stmts
    for ins in fixtures.get("setup", []):
        cols = ", ".join(ins["values"].keys())
        vals = ", ".join(sql_value(v) for v in ins["values"].values())
        setup_lines.append(f"INSERT INTO {ins['table']} ({cols})\nVALUES ({vals});")
    return ("\n".join(setup_lines) + "\n" if setup_lines else NO_FIXTURE,
            "\n".join(teardown_stmts) + "\n" if teardown_stmts else NO_FIXTURE)


# ── 인증 카탈로그 ──────────────────────────────────────────────────────────
def synth_auth(auth, usage):
    """(메소드 자바 코드 or None, 종류: none|cookies|token, 추가 import 셋)"""
    pat = auth.get("pattern", "none")
    p = auth.get("params", {})
    if pat == "none":
        usage["catalog_auth"] += 1
        return None, "none", set()
    if pat == "custom":
        usage["custom_auth"] += 1
        ret = auth.get("returns", "cookies")
        rtype = "CookieFilter" if ret == "cookies" else "String"
        snippet = auth["customSnippet"]
        # T7: 저작 잔존 경로 — 위험 API 차단 (스텁 등록·리플렉션·프로세스 실행 금지)
        banned = ("stubFor", "WireMock.", "Runtime.getRuntime", "ProcessBuilder",
                  "Class.forName", "System.exit", "import ")
        hit = [b for b in banned if b in snippet]
        if hit:
            raise SpecError(f"auth.customSnippet 금지 API 사용: {hit} — 카탈로그 패턴을 쓰거나 스니펫에서 제거")
        body = "\n".join("        " + l for l in snippet.splitlines())
        return (f"    private {rtype} authenticate(Map<String, String> p) {{\n{body}\n    }}\n",
                ret, {"cookie"} if ret == "cookies" else set())
    if pat == "form-login":
        usage["catalog_auth"] += 1
        _ident(p["idParam"], "auth.params.idParam")
        extra = "".join(f'\n                .formParam("{esc_java(k)}", "{esc_java(v)}")'
                        for k, v in p.get("extraFormParams", {}).items())
        code = f"""    private CookieFilter authenticate(Map<String, String> p) {{
        CookieFilter cookies = new CookieFilter();
        given().filter(cookies).baseUri(BASE_URL)
                .contentType(ContentType.URLENC)
                .formParam("{esc_java(p['idField'])}", p.get("{p['idParam']}"))
                .formParam("{esc_java(p['pwField'])}", "{esc_java(p['password'])}"){extra}
        .when().post("{esc_java(p['loginPath'])}")
        .then().statusCode(200);
        return cookies;
    }}
"""
        return code, "cookies", {"cookie", "urlenc"}
    if pat == "session-form-sms":
        usage["catalog_auth"] += 1
        _ident(p["idParam"], "auth.params.idParam")
        _ident(p["certQueryParam"], "auth.params.certQueryParam")
        code = f"""    private CookieFilter authenticate(Map<String, String> p) {{
        CookieFilter cookies = new CookieFilter();
        given().filter(cookies).baseUri(BASE_URL)
                .header("X-Requested-With", "XMLHttpRequest")
                .contentType(ContentType.URLENC)
                .formParam("{esc_java(p['idField'])}", p.get("{p['idParam']}"))
                .formParam("{esc_java(p['pwField'])}", "{esc_java(p['password'])}")
        .when().post("{esc_java(p['loginPath'])}")
        .then().statusCode(200);
        String cert = queryScalar(
                "{esc_java(p['certQuery'])}", Long.parseLong(p.get("{p['certQueryParam']}")));
        if (cert == null) {{
            throw new IllegalStateException("certification not issued");
        }}
        given().filter(cookies).baseUri(BASE_URL)
                .header("X-Requested-With", "XMLHttpRequest")
                .contentType(ContentType.URLENC)
                .formParam("{esc_java(p['idField'])}", p.get("{p['idParam']}"))
                .formParam("{esc_java(p['pwField'])}", "{esc_java(p['password'])}")
                .formParam("{esc_java(p['certField'])}", cert)
        .when().post("{esc_java(p['smsPath'])}")
        .then().statusCode(200);
        return cookies;
    }}
"""
        return code, "cookies", {"cookie", "urlenc"}
    if pat == "bearer-token":
        usage["catalog_auth"] += 1
        body_json = json.dumps(p.get("bodyJson", {}), ensure_ascii=False)
        # ${X} 참조를 자바 문자열 연결로 치환
        java_body = '"' + esc_java(body_json) + '"'
        import re as _re
        java_body = _re.sub(r'\$\{(\w+)\}', lambda m: '" + p.get("%s") + "' % m.group(1), java_body)
        code = f"""    private String authenticate(Map<String, String> p) {{
        return given().baseUri(BASE_URL)
                .contentType(ContentType.JSON)
                .body({java_body})
        .when().post("{esc_java(p['loginPath'])}")
        .then().statusCode(200)
        .extract().jsonPath().getString("{esc_java(p['tokenJsonPath'])}");
    }}
"""
        return code, "token", {"urlenc"}
    raise ValueError(f"unknown auth pattern: {pat}")


# ── 스텁 합성 ──────────────────────────────────────────────────────────────
REQ_KEYS = {"method", "url", "urlPath", "urlPattern", "urlPathPattern", "headers",
            "queryParameters", "bodyPatterns"}   # T9: url 추가
RES_KEYS = {"status", "headers", "jsonBody", "body", "fixedDelayMilliseconds"}


def synth_stub(stub, usage):
    if "rawJson" in stub:
        usage["raw_stub"] += 1
        return stub["rawJson"]
    usage["structured_stub"] += 1
    req = {k: v for k, v in stub["request"].items() if k in REQ_KEYS}
    res = {k: v for k, v in stub["response"].items() if k in RES_KEYS}
    res.setdefault("headers", {"Content-Type": "application/json"})
    return {"request": req, "response": res}


# ── 시드/테스트 렌더 ───────────────────────────────────────────────────────
def param_expr(value):
    v = str(value)
    if v.startswith("${") and v.endswith("}") and v.count("${") == 1:
        return f'p.get("{v[2:-1]}")'
    return f'"{esc_java(v)}"'


def json_body_expr(body):
    """T3: jsonBody의 ${SEED} 참조를 자바 문자열 연결로 치환 (미치환 리터럴 방지).

    직렬화된 JSON에 ${X}가 있으면 " + p.get("X") + " 로 쪼갠다. 없으면 정적 문자열."""
    s = json.dumps(body, ensure_ascii=False)
    esc = esc_java(s)
    if "${" not in esc:
        return f'"{esc}"'
    parts = _re.split(r'\$\{(\w+)\}', esc)   # [lit, name, lit, name, ...]
    out = []
    for i, seg in enumerate(parts):
        if i % 2 == 0:
            if seg:
                out.append(f'"{seg}"')
        else:
            out.append(f'p.get("{seg}")')
    return " + ".join(out) if out else '""'


def render_seed(seed_params):
    lines, entries = [], []
    if any(p.get("kind") == "seq" for p in seed_params):
        lines.append("        long seq = testSeq(info);")
    for p in seed_params:
        k = p.get("kind")
        if k == "seq":
            off = int(p.get("offset", 0))
            expr = "Long.toString(seq)" if off == 0 else f"Long.toString(seq + {off})"
        elif k == "id":
            expr = f'"{esc_java(p.get("prefix", "bb"))}" + testId(info)'
        elif k == "literal":
            expr = f'"{esc_java(p["value"])}"'
        else:
            raise ValueError(f"unknown seed kind: {k}")
        entries.append(f'                "{p["name"]}", {expr}')
    lines.append("        return Map.of(\n" + ",\n".join(entries) + ");")
    return "\n".join(lines)


def render_assertion(a):
    path = esc_java(a["path"])
    if "equalToInt" in a:
        return f'                    .body("{path}", equalTo({int(a["equalToInt"])}))'
    if "equalTo" in a:
        return f'                    .body("{path}", equalTo("{esc_java(a["equalTo"])}"))'
    if "containsString" in a:
        return f'                    .body("{path}", containsString("{esc_java(a["containsString"])}"))'
    if a.get("notNullValue"):
        return f'                    .body("{path}", notNullValue())'
    raise ValueError(f"unknown assertion: {a}")


def render_test(t, spec, auth_kind):
    m = spec["endpoint"]["method"].lower()
    lines = []
    if t.get("comment"):
        lines.append(f"        // {t['comment']}")
    lines.append("        Map<String, String> p = seed(info);")
    lines.append("        arrange(p);")
    if auth_kind == "cookies":
        lines.append("        CookieFilter cookies = authenticate(p);")
    elif auth_kind == "token":
        lines.append("        String token = authenticate(p);")
    lines.append("        try {")
    given = "            given()"
    if auth_kind == "cookies":
        given += ".filter(cookies)"
    given += ".baseUri(BASE_URL)"
    lines.append(given)
    if auth_kind == "token":
        lines.append('                    .header("Authorization", "Bearer " + token)')
    for h, v in (t.get("headers") or {}).items():
        lines.append(f'                    .header("{esc_java(h)}", {param_expr(v)})')
    for k, v in (t.get("pathParams") or {}).items():
        lines.append(f'                    .pathParam("{esc_java(k)}", {param_expr(v)})')
    for k, v in (t.get("query") or {}).items():
        lines.append(f'                    .queryParam("{esc_java(k)}", {param_expr(v)})')
    form = t.get("form") or {}
    if form:
        lines.append("                    .contentType(ContentType.URLENC)")
        for k, v in form.items():
            lines.append(f'                    .formParam("{esc_java(k)}", {param_expr(v)})')
    if t.get("jsonBody") is not None:
        lines.append("                    .contentType(ContentType.JSON)")
        lines.append("                    .body(" + json_body_expr(t["jsonBody"]) + ")")
    lines.append("            .when()")
    lines.append(f'                    .{m}("{esc_java(spec["endpoint"]["path"])}")')
    lines.append("            .then()")
    lines.append(f'                    .statusCode({int(t["expectStatus"])})' +
                 (";" if not t.get("expectBody") else ""))
    asserts = [render_assertion(a) for a in (t.get("expectBody") or [])]
    if asserts:
        asserts[-1] += ";"
        lines += asserts
    else:
        lines[-1] += ";"
    # T2: DB 상태 검증 (steering의 "테스트 본문 JDBC 검증"을 spec으로)
    for da in (t.get("dbAssertions") or []):
        args = ", ".join(param_expr(x) for x in da.get("args", []))
        q = esc_java(da["query"])
        exp = esc_java(str(da["expectEquals"]))
        lines.append(f'            org.junit.jupiter.api.Assertions.assertEquals("{exp}", '
                     f'queryScalar("{q}"{", " + args if args else ""}));')
    lines.append("        } finally {")
    lines.append(f'            executeSqlTemplate("sql/{spec["sqlSlug"]}-teardown.sql", p);')
    lines.append("        }")
    return f"    @Test\n    void {t['name']}(TestInfo info) {{\n" + "\n".join(lines) + "\n    }\n"


def render_class(spec, auth_code, auth_kind, auth_imports, package):
    ep = spec["endpoint"]
    sup = f"{package}.support.BlackBoxSupport"
    ops = set()
    for t in spec["tests"]:
        for a in t.get("expectBody") or []:
            if "containsString" in a:
                ops.add("containsString")
            if "equalTo" in a or "equalToInt" in a:
                ops.add("equalTo")
            if a.get("notNullValue"):
                ops.add("notNullValue")
    uses_form = any((t.get("form") or t.get("jsonBody") is not None) for t in spec["tests"])
    need_urlenc = uses_form or "urlenc" in auth_imports
    imports = [f"import static {sup}.BASE_URL;",
               f"import static {sup}.executeSqlTemplate;"]
    needs_scalar = "queryScalar" in (auth_code or "") or \
        any(t.get("dbAssertions") for t in spec["tests"])
    if needs_scalar:
        imports.append(f"import static {sup}.queryScalar;")
    imports += [f"import static {sup}.testId;",
                f"import static {sup}.testSeq;",
                "import static io.restassured.RestAssured.given;"]
    imports += sorted(f"import static org.hamcrest.Matchers.{o};" for o in ops)
    imports += ["", "import java.util.Map;", "",
                "import org.junit.jupiter.api.Test;",
                "import org.junit.jupiter.api.TestInfo;",
                "import org.junit.jupiter.api.TestInstance;",
                "import org.junit.jupiter.api.parallel.Execution;",
                "import org.junit.jupiter.api.parallel.ExecutionMode;", ""]
    if auth_kind == "cookies" or "cookie" in auth_imports:
        imports.append("import io.restassured.filter.cookie.CookieFilter;")
    if need_urlenc or auth_kind == "token":
        imports.append("import io.restassured.http.ContentType;")
    doc = "\n".join(f" * {l}" for l in spec.get("docLines", []))
    javadoc = (f"/**\n * Black-Box API Integration Test (template-rendered v2)\n *\n"
               f" * @target-controller {ep['controller']} ({ep['controllerFile']})\n"
               f" * @target-api {ep['method']} {ep['path']}\n *\n{doc}\n */")
    arrange = (f'    private void arrange(Map<String, String> p) {{\n'
               f'        executeSqlTemplate("sql/{spec["sqlSlug"]}-teardown.sql", p);\n'
               f'        executeSqlTemplate("sql/{spec["sqlSlug"]}-setup.sql", p);\n    }}\n')
    tests = "\n".join(render_test(t, spec, auth_kind) for t in spec["tests"])
    return (f"package {package};\n\n" + "\n".join(imports) + "\n\n" + javadoc +
            "\n@TestInstance(TestInstance.Lifecycle.PER_METHOD)\n"
            "@Execution(ExecutionMode.CONCURRENT)\n"
            f"class {spec['className']} {{\n\n"
            f"    private Map<String, String> seed(TestInfo info) {{\n{render_seed(spec['seedParams'])}\n    }}\n\n"
            f"{arrange}\n" + (auth_code + "\n" if auth_code else "") + f"{tests}}}\n")


def render_support(cfg, package):
