def merge_json(path, update):
    data = json.loads(path.read_text()) if path.exists() else {}
    for k, v in update.items():
        data[k] = data.get(k, 0) + v if isinstance(v, int) else v
    path.write_text(json.dumps(data, indent=2, ensure_ascii=False))
    return data


def _validate(spec):
    """T8: 렌더 전 spec 계약 검증. 실패 시 필드경로 담은 SpecError."""
    for f in ("endpoint", "className", "sqlSlug", "seedParams", "tests"):
        if f not in spec:
            raise SpecError(f"필수 필드 누락: {f}")
    for f in ("method", "path", "controller", "handler"):
        if f not in spec["endpoint"]:
            raise SpecError(f"endpoint.{f} 누락")
    if not _IDENT.match(spec["className"].split(".")[-1]):
        raise SpecError(f"className 부적합: {spec['className']}")
    seed_names = {p["name"] for p in spec["seedParams"]}
    for p in spec["seedParams"]:
        _ident(p["name"], "seedParams[].name")
        if p.get("kind") not in ("seq", "id", "literal"):
            raise SpecError(f"seedParams[{p.get('name')}].kind 부적합: {p.get('kind')}")
    # auth params required 세트
    auth = spec.get("auth", {"pattern": "none"})
    req = {"form-login": ["loginPath", "idField", "pwField", "idParam", "password"],
           "session-form-sms": ["loginPath", "smsPath", "idField", "pwField", "idParam",
                                 "password", "certField", "certQuery", "certQueryParam"],
           "bearer-token": ["loginPath", "tokenJsonPath"],
           "custom": [], "none": []}
    pat = auth.get("pattern", "none")
    if pat not in req:
        raise SpecError(f"auth.pattern 미지원: {pat}")
    for k in req[pat]:
        if k not in auth.get("params", {}):
            raise SpecError(f"auth.params.{k} 누락 (pattern={pat})")
    if pat == "custom" and "customSnippet" not in auth:
        raise SpecError("auth.customSnippet 누락 (pattern=custom)")
    # ${NAME} 참조 전수 검증 (T8/T12): tests·fixtures의 참조가 seedParams에 있나
    refs = set()
    def collect(o):
        if isinstance(o, str):
            refs.update(_re.findall(r"\$\{(\w+)\}", o))
        elif isinstance(o, dict):
            for v in o.values():
                if isinstance(v, str) and "ref" in o and o.get("ref") == v:
                    refs.add(v)
            for k in ("ref", "refStr"):
                if k in o:
                    refs.add(o[k])
            for v in o.values():
                collect(v)
        elif isinstance(o, list):
            for v in o:
                collect(v)
    collect(spec.get("tests"))
    collect(spec.get("fixtures"))
    if pat != "none":
        for k in ("idParam", "certQueryParam"):
            if k in auth.get("params", {}):
                refs.add(auth["params"][k])
    unknown = refs - seed_names
    if unknown:
        raise SpecError(f"정의되지 않은 시드 참조: {sorted(unknown)} (seedParams={sorted(seed_names)})")


def run(spec_path, project_root):
    root = Path(project_root)
    spec = json.loads(Path(spec_path).read_text())
    _validate(spec)
    usage = {"structured_sql": 0, "raw_sql": 0, "no_fixture": 0, "catalog_auth": 0,
             "custom_auth": 0, "structured_stub": 0, "raw_stub": 0}
    cfg_path = root / ".nimbus/artifacts/support-config.json"
    if cfg_path.exists():
        cfg = json.loads(cfg_path.read_text())
    else:
        cfg = DEFAULT_CONFIG
        usage["missing_support_config"] = 1
        print("[WARN] support-config.json 없음 — 기본값 사용 (prestep에서 작성해야 함)")
    package = _derive_package(spec, cfg)   # T1
    pkg_dir = _pkg_dir(package)
    created = []

    # T10: config 해시가 바뀌면 support 재생성
    import hashlib
    cfg_hash = hashlib.sha1(json.dumps(cfg, sort_keys=True).encode()).hexdigest()[:12]
    support = root / pkg_dir / "support/BlackBoxSupport.java"
    support_src = render_support(cfg, package).replace("@@CFG_HASH@@", cfg_hash)
    if not support.exists() or f"cfg-hash: {cfg_hash}" not in support.read_text():
        support.parent.mkdir(parents=True, exist_ok=True)
        support.write_text(support_src)
        created.append(str(support.relative_to(root)))

    auth_code, auth_kind, auth_imports = synth_auth(spec.get("auth", {"pattern": "none"}), usage)
    cls = root / pkg_dir / f"{spec['className']}.java"
    cls.parent.mkdir(parents=True, exist_ok=True)
    cls.write_text(render_class(spec, auth_code, auth_kind, auth_imports, package))
    created.append(str(cls.relative_to(root)))

    setup_sql, teardown_sql = synth_sql(spec.get("fixtures", {}), usage)
    sql_dir = root / SQL_DIR
    sql_dir.mkdir(parents=True, exist_ok=True)
    (sql_dir / f"{spec['sqlSlug']}-setup.sql").write_text(setup_sql)
    (sql_dir / f"{spec['sqlSlug']}-teardown.sql").write_text(teardown_sql)
    created += [f"{SQL_DIR}/{spec['sqlSlug']}-setup.sql", f"{SQL_DIR}/{spec['sqlSlug']}-teardown.sql"]

    for stub in spec.get("stubs") or []:
        f = root / stub["file"]
        f.parent.mkdir(parents=True, exist_ok=True)
        f.write_text(json.dumps(synth_stub(stub, usage), indent=2, ensure_ascii=False))
        created.append(stub["file"])

    art = root / ".nimbus/artifacts"
    art.mkdir(parents=True, exist_ok=True)
    merge_json(art / "template-usage.json", usage)
    key = f"{spec['endpoint']['method']} {spec['endpoint']['path']}"
    mf = art / "manifest.json"
    data = json.loads(mf.read_text()) if mf.exists() else {}
    data[key] = {"status": "ok", "files": created}
    mf.write_text(json.dumps(data, indent=2, ensure_ascii=False))
    print(f"[OK] rendered {key}:")
    for c in created:
        print(f"  {c}")


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--spec", required=True)
    ap.add_argument("--project-root", default=".")
    a = ap.parse_args()
    try:
        run(a.spec, a.project_root)
    except SpecError as e:   # T8: 검증 실패는 필드경로 메시지 + non-zero
        print(f"[SPEC ERROR] {a.spec}: {e}", file=sys.stderr)
        sys.exit(2)


if __name__ == "__main__":
    main()

