                    .body("userId", equalTo("user-beta"))
                    .body("title", equalTo("Daily gratitude log"))
                    .body("category", equalTo("daily"))
                    .body("content", equalTo("Small wins today: finished the report and had lunch with a friend."))
                    .body("nickname", equalTo("QuietOwl"))
                    .body("likes", equalTo(0))
                    .body("createdAt", notNullValue());
            org.junit.jupiter.api.Assertions.assertEquals("0", queryScalar("SELECT likes FROM post WHERE id = ?", p.get("ID2")));
        } finally {
            executeSqlTemplate("sql/internal-posts-get-by-id-teardown.sql", p);
        }
    }

    @Test
    void NTC_getPost_maxLengthId(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .pathParam("id", p.get("ID_MAX"))
            .when()
                    .get("/internal/posts/{id}")
            .then()
                    .statusCode(200)
                    .body("userId", equalTo("user-gamma"))
                    .body("title", equalTo("Boundary length id smoke test"))
                    .body("category", equalTo("career"))
                    .body("content", equalTo("Verifies exact 64-character primary key still resolves correctly."))
                    .body("moodEmoji", equalTo("🙂"))
                    .body("nickname", equalTo("LongIdFox"))
                    .body("likes", equalTo(3))
                    .body("createdAt", notNullValue());
            org.junit.jupiter.api.Assertions.assertEquals("64", queryScalar("SELECT LENGTH(id) FROM post WHERE id = ?", p.get("ID_MAX")));
        } finally {
            executeSqlTemplate("sql/internal-posts-get-by-id-teardown.sql", p);
        }
    }

